import React from 'react';

type ButtonProps = {
  label: string;           // Required string
  onClick: () => void;     // Required function
  isDisabled?: boolean;    // Optional boolean
  children?: React.ReactNode; // Optional React elements inside the tag
};

// Modern approach: Typing the arguments directly
export function Button({ label, onClick, isDisabled = false, children }: ButtonProps) {
  return (
    <button onClick={onClick} disabled={isDisabled}>
      {label}
      {children}
    </button>
  );
}

// USAGE (TS will throw an error if 'label' or 'onClick' are missing!)
